const D=window.ARCHITECTURE_M01L01,S=D.screens,SE=D.segments,K='architecture-m01l01-prototype-v1';let i=0,st={};try{st=JSON.parse(localStorage.getItem(K)||'{}')}catch(e){}const q=s=>document.querySelector(s),e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){localStorage.setItem(K,JSON.stringify(st))}function extra(s){if(s.type==='lesson_cover')return `<section class="hero"><p class="eye">${e(s.eyebrow)}</p><h1>${e(s.title)}</h1><p>${e(s.subtitle)}</p><div class="question"><small>Управленческий вопрос</small><b>${e(s.management_question)}</b></div><div class="box" style="color:#0b2948"><b>Результат:</b> ${e(s.result)}</div></section>`;if(s.type==='system_map')return `<section class="card"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><div class="map"><span class="t">Внешняя среда</span><span class="l">Входы</span><span class="r">Выходы</span><span class="b">Ограничения</span><strong>ОБЪЕКТ<br>УПРАВЛЕНИЯ</strong></div><div class="grid two">${s.legend.map(x=>`<div class="item"><b>${e(x.label)}</b><small>${e(x.value)}</small></div>`).join('')}</div><div class="note">${e(s.takeaway)}</div></section>`;if(s.type==='micro_check'||s.type==='quiz'){let a=st.answers?.[s.id],c=st.checked?.[s.id];return `<section class="card"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><p>${e(s.question)}</p><div class="opts">${s.options.map(o=>`<button class="opt ${a===o.id?'sel':''} ${c?(o.id===s.correct?'ok':a===o.id?'no':''):''}" data-a="${o.id}"><b>${o.id}. ${e(o.text)}</b></button>`).join('')}</div>${c?`<div class="note ${a===s.correct?'':'warn'}">${e(a===s.correct?s.correct_feedback:s.wrong_feedback)}</div>`:''}</section>`}if(s.type==='micro_practice'){let v=st.practice||{};return `<section class="card"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><p>${e(s.instruction)}</p>${s.fields.map(f=>`<div class="field"><label>${e(f.label)}</label><textarea data-f="${f.id}" placeholder="${e(f.placeholder)}">${e(v[f.id]||'')}</textarea></div>`).join('')}<div class="note">Заполнено ${s.fields.filter(f=>(v[f.id]||'').trim()).length} из ${s.fields.length}</div></section>`}if(s.type==='case_story')return `<section class="card"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><div class="line"><b>Было</b><span>${e(s.before)}</span></div><div class="line"><b>Факты</b><span>${s.evidence.map(x=>'• '+e(x)).join('<br>')}</span></div><div class="line"><b>Решение</b><span>${e(s.decision)}</span></div><div class="line"><b>Стало</b><span>${e(s.after)}</span></div></section>`;if(s.type==='comparison')return `<section class="card"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><div class="grid two">${s.cards.map(c=>`<div class="item"><b>${e(c.title)}</b>${c.signal?`<small>${e(c.signal)}</small><div class="chip">${e(c.mode)}</div>`:`<small>${c.items.map(x=>'• '+e(x)).join('<br>')}</small>`}</div>`).join('')}</div><div class="note">${e(s.decision_rule)}</div></section>`;if(s.type==='anti_patterns')return `<section class="card"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><div class="grid">${s.patterns.map(x=>`<div class="item"><b>${e(x.title)}</b><small>${e(x.consequence)}</small></div>`).join('')}</div></section>`;if(s.type==='summary')return `<section class="card"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><div class="grid">${s.takeaways.map((x,n)=>`<div class="item"><b>${n+1}</b> ${e(x)}</div>`).join('')}</div><div class="note"><b>Создано:</b> ${e(s.artifact)}</div></section>`;if(s.type==='lesson_result')return `<section class="hero"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2><div class="box" style="color:#0b2948"><b>${e(s.status)}</b><br>${e(s.artifact)}</div><p>${e(s.next_use)}</p><div class="question"><b>${e(s.business_note)}</b></div></section>`;let body=(s.body||[]).map(x=>`<p>${e(x)}</p>`).join(''),tail=s.example?`<div class="box"><b>Пример</b><p>${e(s.example)}</p></div>`:'';if(s.warning)tail+=`<div class="note warn">${e(s.warning)}</div>`;if(s.callout)tail+=`<div class="note">${e(s.callout)}</div>`;if(s.prompt)tail+=`<div class="note">${e(s.prompt)}</div>${(s.chips||[]).map(x=>`<span class="chip">${e(x)}</span>`).join('')}`;if(s.steps)tail+=`<div class="grid">${s.steps.map((x,n)=>`<div class="item"><b>${n+1}</b> ${e(x)}</div>`).join('')}</div>`;return `<section class="${s.type==='key_idea'?'hero':'card'}"><p class="eye">${e(s.eyebrow)}</p><h2>${e(s.title)}</h2>${body}${tail}</section>`}function render(){let s=S[i],a=SE.indexOf(s.segment);q('#segs').innerHTML=SE.map((x,n)=>`<i class="${n<a?'d':n===a?'a':''}"></i>`).join('');q('#meta').textContent=s.segment;q('#pct').textContent=Math.round((i+1)/S.length*100)+'%';q('#view').innerHTML=extra(s);q('#prev').disabled=i===0;q('#next').textContent=s.primary_action||'Продолжить';q('#count').textContent=`Экран ${i+1} из ${S.length}`;qAll('.opt').forEach(b=>b.onclick=()=>{if(st.checked?.[s.id])return;st.answers=st.answers||{};st.answers[s.id]=b.dataset.a;save();render()});qAll('[data-f]').forEach(t=>t.oninput=()=>{st.practice=st.practice||{};st.practice[t.dataset.f]=t.value;save()});q('#view').scrollTop=0}function qAll(x){return document.querySelectorAll(x)}q('#prev').onclick=()=>{if(i){i--;render()}};q('#next').onclick=()=>{let s=S[i];if((s.type==='micro_check'||s.type==='quiz')&&!st.checked?.[s.id]){if(!st.answers?.[s.id])return alert('Сначала выберите ответ.');st.checked=st.checked||{};st.checked[s.id]=true;save();return render()}if(s.type==='micro_practice'&&s.fields.filter(f=>((st.practice||{})[f.id]||'').trim()).length<4)return alert('Заполните минимум 4 поля.');if(i<S.length-1){i++;render()}else alert('Прототип завершён.')};q('#reset').onclick=()=>{localStorage.removeItem(K);st={};i=0;render()};let u=new URL(location.href),n=+u.searchParams.get('screen');if(n>=1&&n<=S.length)i=n-1;if(u.searchParams.get('demo')==='1'){st.practice={object:'Открытие третьей точки',result:'Проверить спрос, самостоятельную команду и денежный порог',inside:'Спрос, команда, мощность, запуск и деньги',outside:'Дальнейшая сеть',owner:'Собственник: пилот или stop'};save()}render();
